{
 "summary": "The Lean theorem states that for n ≥ 3, k ≥ 1, R > 0 and positive r_1..r_k, the following are equivalent. (1) There exist open neighborhoods U_i of the closed capacity-r_i balls in ℂ^n, with smooth topological embeddings f_i : U_i → ℂ^n that preserve the standard symplectic form, sending each closed ball into the open capacity-R ball, with pairwise disjoint images of the closed balls. (2) Σ r_i^n < R^n and r_i + r_j < R for i ≠ j. This matches Theorem 1.1 of the paper. No substantive caveat was found. The only nuance is that the neighborhood U_i is not itself required to map into the target, which is harmless because the neighborhood can be shrunk.",
 "glossary": [
  {"decl": "Phase", "line": 8, "plain": "ℂ^n, i.e. ℝ^{2n}", "standard_concept": "phase space ℂ^n", "matches_standard": "yes", "note": ""},
  {"decl": "capacity", "line": 10, "plain": "π Σ_j |z_j|^2", "standard_concept": "capacity π|z|^2 (π times squared radius)", "matches_standard": "yes", "note": ""},
  {"decl": "closedBall", "line": 13, "plain": "B^{2n}(r) = {z : π|z|^2 ≤ r}", "standard_concept": "closed ball of capacity r", "matches_standard": "yes", "note": ""},
  {"decl": "openBall", "line": 15, "plain": "int B^{2n}(r) = {z : π|z|^2 < r}", "standard_concept": "open ball of capacity r", "matches_standard": "yes", "note": ""},
  {"decl": "standardForm", "line": 17, "plain": "ω0(u,v) = Σ_j (x_j(u) y_j(v) − y_j(u) x_j(v))", "standard_concept": "standard symplectic form Σ dx_j∧dy_j", "matches_standard": "yes", "note": "Real subtraction; the sign convention is irrelevant for preservation."},
  {"decl": "SymplecticOn", "line": 20, "plain": "U is open, f is C^∞ on U, f|_U is a topological embedding, and Df(x) preserves ω0 for every x ∈ U", "standard_concept": "symplectic embedding defined on open U", "matches_standard": "yes", "note": "Df(x) is symplectic linear, hence injective, so f is an immersion. An immersion that is a topological embedding is a smooth embedding. fderiv is genuine since f is smooth on open U."},
  {"decl": "HasPacking", "line": 26, "plain": "There exist open U_i ⊇ B(r_i) and symplectic embeddings f_i on U_i with f_i(B(r_i)) ⊆ int B(R), and f_i(B(r_i)) disjoint from f_j(B(r_j)) for i ≠ j", "standard_concept": "symplectic embedding ⊔ B^{2n}(R_i) ↪ int B^{2n}(R)", "matches_standard": "yes", "note": "Only the closed ball, not U_i, must map into the target. This is equivalent, since U_i can be shrunk by compactness."},
  {"decl": "PackingInequalities", "line": 33, "plain": "Σ r_i^n < R^n and r_i + r_j < R for i ≠ j", "standard_concept": "conditions (1.1)", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "main_theorem", "line": 36, "plain": "For naturals n ≥ 3, k ≥ 1, real R > 0, and r : Fin k → ℝ with all r_i > 0: HasPacking n k R r ↔ (Σ r_i^n < R^n ∧ ∀ i ≠ j, r_i + r_j < R)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For n ≥ 3, k ≥ 1 and positive R, R_1..R_k, there is a symplectic embedding ⊔ B^{2n}(R_i) ↪ int B^{2n}(R) iff Σ R_i^n < R^n and R_i + R_j < R for i < j. Here embeddings of closed balls are defined on open neighborhoods and have pairwise disjoint compact images."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "main_theorem", "relation": "equivalent", "why": "Same dimension and count hypotheses, the same capacity convention, closed source and open target, embeddings on neighborhoods, disjoint images, and the same inequalities."}
 ],
 "flags": [
  {"id": "F1", "category": "other", "severity": "low", "decl": "HasPacking", "line": 29, "paper_ref": "Theorem 1.1", "explanation": "The neighborhood U_i is not required to map into int B(R); only the closed ball is. The paper's notion presumably has the whole embedding land in the target. These are equivalent, since f_i^{-1}(int B(R)) ∩ U_i is an open neighborhood of the compact ball. So this is not a mismatch, just a presentational difference.", "polarity": "n/a", "probe_idea": "Prove that HasPacking implies the variant requiring Set.MapsTo (f i) (U i) (openBall n R), by shrinking U i to U i ∩ f i ⁻¹' openBall n R."},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "SymplecticOn", "line": 22, "paper_ref": "Theorem 1.1", "explanation": "The embedding is required to be topological, plus smooth with symplectic derivative, rather than a smooth embedding stated directly. This is equivalent because a symplectic linear map is injective.", "polarity": "n/a", "probe_idea": "Show that ∀ x ∈ U, Function.Injective (fderiv ℝ f x) follows from the form-preservation clause, using the nondegeneracy of standardForm."}
 ],
 "lint_verdicts": [
  {"line": 18, "rule": "nat-sub", "verdict": "harmless", "why": "The subtraction is in ℝ (products of real and imaginary parts), not ℕ."},
  {"line": 24, "rule": "junk-deriv", "verdict": "harmless", "why": "x ranges over the open set U on which f is C^∞, so f is differentiable at x and fderiv is the true derivative."}
 ]
}
